syntax = "proto3";

package ji.hcp.v1;

option java_multiple_files = true;
option java_package = "io.github.diodeme.ji.hcp.v1";
option java_outer_classname = "HcpProto";

message Envelope {
  uint32 protocol_version = 1;
  string connection_id = 2;
  oneof payload {
    Command command = 10;
    DurableEvent durable_event = 11;
    TransientStream transient_stream = 12;
    SnapshotChunk snapshot_chunk = 13;
    ErrorDetail error = 14;
  }
}

message Command {
  string command_id = 1;
  string session_id = 2;
  uint64 expected_revision = 3;
  bytes payload = 4;
}

message DurableEvent {
  uint64 event_seq = 1;
  uint64 snapshot_revision = 2;
  string event_type = 3;
  bytes payload = 4;
}

message TransientStream {
  string run_id = 1;
  uint64 stream_epoch = 2;
  uint64 stream_seq = 3;
  bytes payload = 4;
}

message SnapshotChunk {
  uint64 snapshot_revision = 1;
  uint32 chunk_index = 2;
  uint32 chunk_count = 3;
  bytes payload = 4;
  bytes total_sha256 = 5;
}

message ErrorDetail {
  string code = 1;
  map<string, string> parameters = 2;
  optional string trace_id = 3;
  optional uint64 retry_after_millis = 4;
  optional uint64 current_revision = 5;
}
